namespace ghidra.app.plugin.core.datamgr.actions;






using docking;
using docking.widgets.combobox;
using ghidra.app.util;
using ghidra.program.model.data;
using ghidra.util;

/**
 * A simple dialog to select the language export type.
 */
class AnnotationHandlerDialog : DialogComponentProvider {

	private GhidraComboBox<AnnotationHandler> handlerComboBox;
	private List<AnnotationHandler> handlerList;
	private AnnotationHandler handler;

	private bool success;

	AnnotationHandlerDialog(List<AnnotationHandler> handlerList) : base("Export Format")
    {
		this.handlerList = handlerList;

		addWorkPanel(create());
		addOKButton();
		addCancelButton();
		setOkEnabled(true);
		setHelpLocation(new HelpLocation(HelpTopics.DATA_MANAGER, "Export_To"));
		setRememberSize(false);

	}

	/* @Override */
	protected void cancelCallback() {
		close();
	}

	/* @Override */
	protected void okCallback() {
		object[] objs = handlerComboBox.getSelectedObjects();
		if (objs != null && objs.length > 0) {
			handler = (AnnotationHandler) objs[0];
		}
		success = true;
		close();
	}

	JPanel create() {
		JPanel outerPanel = new JPanel(new BorderLayout());
		outerPanel.getAccessibleContext().setAccessibleName("Annotation Handler");
		handlerComboBox = new(handlerList);
		handlerComboBox.getAccessibleContext().setAccessibleName("Combo Box");
		outerPanel.add(handlerComboBox, BorderLayout.NORTH);
		return outerPanel;
	}

	public AnnotationHandler getHandler() {
		return handler;
	}

	public bool wasSuccessful() {
		return success;
	}
}
